#include "dsp/cleansweep_filter.h"
#include <cmath>
#include <cstdio>
#include <initializer_list>
static double response(mpc::dsp::CleansweepOnePole::Mode mode,double sr,double hz,double probe){mpc::dsp::CleansweepOnePole f(mode);f.setCutoff(static_cast<float>(hz),sr);const int n=32768,skip=8192;double sum=0;for(int i=0;i<n;++i){float x=static_cast<float>(std::sin(2*3.141592653589793*probe*i/sr));float y=f.process(x);if(i>=skip)sum+=double(y)*y;}return std::sqrt(sum/(n-skip))*std::sqrt(2.0);}
int main(){const double rates[]={44100,48000,96000};for(double sr:rates)for(double fc:{100.0,1000.0,5000.0}){double hp=response(mpc::dsp::CleansweepOnePole::Mode::Highpass,sr,fc,fc),lp=response(mpc::dsp::CleansweepOnePole::Mode::Lowpass,sr,fc,fc);if(std::fabs(hp-0.70710678)>0.012||std::fabs(lp-0.70710678)>0.012){std::fprintf(stderr,"-3 dB cutoff mismatch sr=%.0f fc=%.0f hp=%.6f lp=%.6f\n",sr,fc,hp,lp);return 1;}double hpl=response(mpc::dsp::CleansweepOnePole::Mode::Highpass,sr,fc,fc/4),hph=response(mpc::dsp::CleansweepOnePole::Mode::Highpass,sr,fc,fc*4),lpl=response(mpc::dsp::CleansweepOnePole::Mode::Lowpass,sr,fc,fc/4),lph=response(mpc::dsp::CleansweepOnePole::Mode::Lowpass,sr,fc,fc*4);if(!(hpl<hph&&lpl>lph))return 2;}std::puts("Cleansweep first-order response checks passed");return 0;}
